import { addCollection } from '@iconify/vue'
import type { IconifyJSON } from '@iconify/types'
import lucideSubset from '@/assets/icons/lucide-subset.json'

/**
 * Registers an offline subset of Lucide icons with Iconify.
 *
 * The subset is generated by `scripts/build-icon-subset.mjs`, so no network
 * request is ever made for an icon and the bundle only ships what the page uses.
 */
export function registerIcons(): void {
  addCollection(lucideSubset as IconifyJSON)
}
